DROP POLICY pedidos_cliente_sel ON pedidos;
CREATE POLICY pedidos_cliente_sel ON pedidos AS PERMISSIVE FOR SELECT TO cliente
  USING (cliente_id = (NULLIF(current_setting('app.cliente_id', true), ''))::integer);

DROP POLICY pedidos_cliente_ins ON pedidos;
CREATE POLICY pedidos_cliente_ins ON pedidos AS PERMISSIVE FOR INSERT TO cliente
  WITH CHECK (cliente_id = (NULLIF(current_setting('app.cliente_id', true), ''))::integer);

REVOKE admin_bd FROM atendente;
ALTER TABLE funcionarios FORCE ROW LEVEL SECURITY;
ALTER TABLE pedidos FORCE ROW LEVEL SECURITY;

DROP POLICY pedidos_equipe ON pedidos;
CREATE POLICY pedidos_equipe_sel ON pedidos AS PERMISSIVE FOR SELECT TO atendente, gerente USING (true);
CREATE POLICY pedidos_atendente_ins ON pedidos AS PERMISSIVE FOR INSERT TO atendente WITH CHECK (true);
